import React, { useState, useEffect, useRef } from 'react';
import { Storage } from '../../utils/storage';
import { sounds } from '../../utils/sound';
import { Icons } from './Icons';
import { PepinoState } from '../../types';

interface FishTankProps {
    onRewardClaim: (amount: number, isPoop: boolean) => void;
}

export const FishTank: React.FC<FishTankProps> = ({ onRewardClaim }) => {
    const [pepinoState, setPepinoState] = useState<PepinoState>(Storage.getPepinoState());
    const [isGiftReady, setIsGiftReady] = useState(false);
    const [poopVisible, setPoopVisible] = useState(false);

    // Fish movement state
    const [fishPos, setFishPos] = useState({ x: 50, y: 50 }); // Percentage
    const [fishDirection, setFishDirection] = useState<'left' | 'right'>('right');
    const containerRef = useRef<HTMLDivElement>(null);

    // Timer check
    useEffect(() => {
        const checkTime = () => {
            const now = Date.now();
            const readyTime = pepinoState.lastGiftTime + pepinoState.nextGiftDelay;

            if (now >= readyTime) {
                setIsGiftReady(true);
            } else {
                setIsGiftReady(false);
            }
        };

        checkTime();
        const interval = setInterval(checkTime, 5000); // Check every 5s
        return () => clearInterval(interval);
    }, [pepinoState]);

    // Random Swimming Logic
    useEffect(() => {
        let timeoutId: any;

        const moveFish = () => {
            // Generate new target position (10% to 90% range to keep inside)
            const newX = 15 + Math.random() * 70;
            const newY = 25 + Math.random() * 50; // Keep slightly away from top/bottom

            // Instant cut for direction change
            setFishDirection(newX > fishPos.x ? 'right' : 'left');
            setFishPos({ x: newX, y: newY });

            // Random delay before next move (3s to 8s)
            const delay = 3000 + Math.random() * 5000;
            timeoutId = setTimeout(moveFish, delay);
        };

        // Start swimming
        moveFish();

        return () => clearTimeout(timeoutId);
    }, []); 

    const handleClaim = (e: React.MouseEvent) => {
        e.stopPropagation();
        if (!isGiftReady && !poopVisible) return;

        // Reset Logic
        // Random 2-3 hours delay (2h = 7200000ms, 3h = 10800000ms)
        const minDelay = 7200000;
        const maxDelay = 10800000;
        const nextDelay = Math.floor(Math.random() * (maxDelay - minDelay + 1) + minDelay);

        Storage.updatePepinoGiftTime(nextDelay);
        setPepinoState(Storage.getPepinoState()); // Sync local state
        setIsGiftReady(false);

        if (poopVisible) {
            setPoopVisible(false);
            onRewardClaim(1, true); // +1 for cleaning
            sounds.playPop();
            return;
        }

        // Random Reward Logic
        const r = Math.random();
        let amount = 0;
        let isPoop = false;

        if (r < 0.05) {
            // 5% Poop
            isPoop = true;
            setPoopVisible(true);
            return; 
        } else if (r < 0.10) {
            // 5% +20 (0.05 to 0.10)
            amount = 20;
        } else if (r < 0.20) {
            // 10% +15 (0.10 to 0.20)
            amount = 15;
        } else if (r < 0.50) {
            // 30% +10 (0.20 to 0.50)
            amount = 10;
        } else {
            // 50% +5 (0.50 to 1.00)
            amount = 5;
        }

        if (amount > 0) {
            sounds.playWin();
            onRewardClaim(amount, false);
        }
    };

    return (
        <div 
            ref={containerRef}
            // Removed heavy border, using subtle ring or just shadow
            className="w-full h-40 relative rounded-[1.75rem] overflow-hidden bg-[#e0f7fa] shadow-inner mb-6 select-none"
        >
            {/* Water Gradient */}
            <div className="absolute inset-0 bg-gradient-to-b from-[#e0f7fa] via-[#e0f7fa] to-[#b2ebf2]" />

            {/* Background Decor (Sand Hills) */}
            <div className="absolute inset-x-0 bottom-0 h-12 w-full">
                <svg viewBox="0 0 100 20" preserveAspectRatio="none" className="w-full h-full text-[#E3D8C8] opacity-90 fill-current">
                    <path d="M0,20 Q25,5 50,15 T100,10 V20 H0 Z" />
                </svg>
            </div>

            {/* Organic Plants (SVG) - Left */}
            <div className="absolute bottom-2 left-6 w-10 h-16 origin-bottom animate-sway-slow opacity-80">
                <svg viewBox="0 0 100 100" fill="#4ade80">
                    <path d="M45,100 Q40,60 20,30 Q30,60 48,100 Z" />
                    <path d="M50,100 Q55,50 70,20 Q65,60 55,100 Z" />
                    <path d="M55,100 Q65,70 85,40 Q75,70 60,100 Z" />
                </svg>
            </div>

            {/* Organic Plants (SVG) - Right */}
            <div className="absolute bottom-4 right-10 w-8 h-12 origin-bottom animate-sway opacity-80">
                <svg viewBox="0 0 100 100" fill="#86efac">
                    <path d="M50,100 C20,60 80,40 50,0 C60,40 30,70 60,100 Z" />
                </svg>
            </div>

            {/* PEPINO & BUBBLE CONTAINER */}
            <div 
                className="absolute w-12 h-12 transition-all duration-[3000ms] ease-in-out"
                style={{ 
                    left: `${fishPos.x}%`, 
                    top: `${fishPos.y}%`,
                    transform: `translate(-50%, -50%)`
                }}
            >
                 {/* Fish Wrapper - Instant Cut Direction (No transition) */}
                 <div className={`w-full h-full relative ${fishDirection === 'left' ? '-scale-x-100' : 'scale-x-100'}`}>

                    {/* RED BETTA FISH SVG (Detailed) */}
                    <svg viewBox="0 0 100 60" className="w-full h-full drop-shadow-sm filter" style={{ filter: 'drop-shadow(0 2px 2px rgba(0,0,0,0.1))' }}>
                         {/* Large Flowing Tail */}
                         <path d="M10,30 Q-5,10 5,5 Q10,20 20,25 Q15,40 5,55 Q-5,50 10,30" fill="#ef4444" opacity="0.9" />
                         {/* Top Fin (Dorsal) */}
                         <path d="M45,20 Q35,5 55,5 Q60,15 65,22" fill="#ef4444" opacity="0.9" />
                         {/* Bottom Fin (Anal) */}
                         <path d="M45,40 Q35,55 55,55 Q65,50 70,38" fill="#ef4444" opacity="0.9" />
                         {/* Body */}
                         <path d="M20,30 Q25,15 60,20 Q85,25 90,30 Q85,35 60,40 Q25,45 20,30 Z" fill="#ef4444" />
                         {/* Side Fin (Pectoral) */}
                         <path d="M55,30 Q50,35 58,40 Q62,35 55,30" fill="#fca5a5" opacity="0.8" />
                         {/* Eye */}
                         <circle cx="80" cy="27" r="1.5" fill="black" />
                    </svg>

                    {/* GIFT BUBBLE - Attached closely to fish */}
                    {isGiftReady && (
                        <div 
                            onClick={handleClaim}
                            // Reset scale so text/icon isn't flipped with the fish
                            className={`absolute -top-6 left-1/2 -translate-x-1/2 z-20 cursor-pointer animate-bounce ${fishDirection === 'left' ? '-scale-x-100' : ''}`}
                        >
                            <div className="bg-white/90 backdrop-blur-sm p-1 rounded-full shadow-md border border-blue-200 animate-bubble-float hover:scale-110 transition-transform">
                                <Icons.Gift className="w-3 h-3 text-blue-500 fill-current" />
                            </div>
                        </div>
                    )}
                 </div>
            </div>

            {/* POOP (Stationary at bottom) */}
            {poopVisible && (
                <div 
                    onClick={handleClaim}
                    className="absolute bottom-6 left-1/2 -translate-x-1/2 z-20 cursor-pointer hover:scale-110 transition-transform animate-bounce"
                >
                    <span className="text-xl filter drop-shadow-md">💩</span>
                </div>
            )}

            {/* Tank Shine/Glass Reflection */}
            <div className="absolute top-0 right-0 w-32 h-32 bg-gradient-to-bl from-white/30 to-transparent pointer-events-none rounded-bl-full" />
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { Storage } from '../../utils/storage';
import { sounds } from '../../utils/sound';
import { Icons } from './Icons';
import { PepinoState } from '../../types';

interface FishTankProps {
    onRewardClaim: (amount: number, isPoop: boolean) => void;
    showIntro?: boolean;
}

export const FishTank: React.FC<FishTankProps> = ({ onRewardClaim, showIntro = false }) => {
    const [pepinoState, setPepinoState] = useState<PepinoState>(Storage.getPepinoState());
    const [isGiftReady, setIsGiftReady] = useState(false);
    const [poopVisible, setPoopVisible] = useState(false);
    const [rewardFeedback, setRewardFeedback] = useState<{amount: number, isPoop: boolean} | null>(null);

    // Intro State: 'message' -> 'building' -> 'active'
    const [introPhase, setIntroPhase] = useState<'message' | 'building' | 'active'>(showIntro ? 'message' : 'active');

    // Fish movement state
    const [fishPos, setFishPos] = useState({ x: 50, y: 50 }); // Percentage
    const [fishDirection, setFishDirection] = useState<'left' | 'right'>('right');
    const containerRef = useRef<HTMLDivElement>(null);

    // Handle Intro Flow
    useEffect(() => {
        if (showIntro) {
            // Step 1: Message lasts 7s
            const timer1 = setTimeout(() => {
                setIntroPhase('building');

                // Step 2: Fade in tank components (building phase), then active
                setTimeout(() => {
                    setIntroPhase('active');
                }, 1000); 
            }, 7000);
            return () => clearTimeout(timer1);
        }
    }, [showIntro]);

    // Timer check
    useEffect(() => {
        const checkTime = () => {
            const now = Date.now();
            const readyTime = pepinoState.lastGiftTime + pepinoState.nextGiftDelay;

            if (now >= readyTime) {
                setIsGiftReady(true);
            } else {
                setIsGiftReady(false);
            }
        };

        checkTime();
        const interval = setInterval(checkTime, 5000); // Check every 5s
        return () => clearInterval(interval);
    }, [pepinoState]);

    // Random Swimming Logic
    useEffect(() => {
        let timeoutId: any;

        const moveFish = () => {
            // Generate new target position
            // X: 15-85% (avoid walls)
            const newX = 15 + Math.random() * 70;
            // Y: 30-80% (avoid top 30px, stay somewhat off bottom)
            const newY = 30 + Math.random() * 50; 

            // Instant cut for direction change
            setFishDirection(newX > fishPos.x ? 'right' : 'left');
            setFishPos({ x: newX, y: newY });

            // Random delay before next move (3s to 8s)
            const delay = 3000 + Math.random() * 5000;
            timeoutId = setTimeout(moveFish, delay);
        };

        // Start swimming
        moveFish();

        return () => clearTimeout(timeoutId);
    }, []); 

    const handleClaim = (e: React.MouseEvent) => {
        e.stopPropagation();
        if (!isGiftReady && !poopVisible) return;

        // Reset Logic
        // Random 2-3 hours delay
        const minDelay = 7200000;
        const maxDelay = 10800000;
        const nextDelay = Math.floor(Math.random() * (maxDelay - minDelay + 1) + minDelay);

        Storage.updatePepinoGiftTime(nextDelay);
        setPepinoState(Storage.getPepinoState()); // Sync local state
        setIsGiftReady(false);

        if (poopVisible) {
            setPoopVisible(false);
            onRewardClaim(1, true); // +1 for cleaning
            setRewardFeedback({ amount: 1, isPoop: true });
            sounds.playPop();
            setTimeout(() => setRewardFeedback(null), 2000);
            return;
        }

        // Random Reward Logic
        const r = Math.random();
        let amount = 0;
        let isPoop = false;

        if (r < 0.05) {
            isPoop = true;
            setPoopVisible(true);
            return; 
        } else if (r < 0.10) {
            amount = 20;
        } else if (r < 0.20) {
            amount = 15;
        } else if (r < 0.50) {
            amount = 10;
        } else {
            amount = 5;
        }

        if (amount > 0) {
            sounds.playWin();
            onRewardClaim(amount, false);
            setRewardFeedback({ amount, isPoop: false });
            setTimeout(() => setRewardFeedback(null), 2000);
        }
    };

    if (introPhase === 'message') {
        return (
            <div className="w-full h-52 flex flex-col items-center justify-center p-6 text-center animate-fade-in-medium">
                <p className="text-xl font-bold text-stone-800 dark:text-stone-100 mb-2 leading-tight">This is Pepino.</p>
                <p className="text-sm font-medium text-stone-600 dark:text-stone-400 mb-4 leading-relaxed">He was around while Oku was being built.</p>
                <p className="text-xs text-stone-500 dark:text-stone-500 font-semibold opacity-80 animate-slide-up">Thanks for supporting the app — feel free to check on him anytime.</p>
            </div>
        );
    }

    const isBuilding = introPhase === 'building';

    return (
        <div 
            ref={containerRef}
            // H-52 height (approx 208px), increased size
            className={`w-full h-52 relative rounded-[1.75rem] overflow-hidden bg-[#e0f7fa] shadow-inner mb-6 select-none transition-opacity duration-1000 ${isBuilding ? 'opacity-0' : 'opacity-100'}`}
        >
            {/* Water Gradient */}
            <div className="absolute inset-0 bg-gradient-to-b from-[#e0f7fa] via-[#e0f7fa] to-[#b2ebf2]" />

            {/* Background Decor (Sand Hills - Taller) */}
            <div className={`absolute inset-x-0 bottom-0 h-20 w-full transition-transform duration-1000 ${isBuilding ? 'translate-y-full' : 'translate-y-0'}`}>
                <svg viewBox="0 0 100 20" preserveAspectRatio="none" className="w-full h-full text-[#E3D8C8] opacity-90 fill-current">
                    <path d="M0,20 L0,5 Q20,15 40,8 T80,12 L100,6 L100,20 Z" />
                </svg>
            </div>

            {/* Organic Plants (SVG) - Left Group */}
            <div className={`absolute bottom-4 left-6 w-12 h-20 origin-bottom animate-sway-slow opacity-80 transition-opacity duration-1000 delay-300 ${isBuilding ? 'opacity-0' : 'opacity-80'}`}>
                <svg viewBox="0 0 100 100" fill="#4ade80">
                    <path d="M45,100 Q40,60 20,30 Q30,60 48,100 Z" />
                    <path d="M50,100 Q55,50 70,20 Q65,60 55,100 Z" />
                    <path d="M55,100 Q65,70 85,40 Q75,70 60,100 Z" />
                </svg>
            </div>

            {/* Organic Plants (SVG) - Right Group */}
            <div className={`absolute bottom-6 right-10 w-8 h-14 origin-bottom animate-sway opacity-80 transition-opacity duration-1000 delay-500 ${isBuilding ? 'opacity-0' : 'opacity-80'}`}>
                <svg viewBox="0 0 100 100" fill="#86efac">
                    <path d="M50,100 C20,60 80,40 50,0 C60,40 30,70 60,100 Z" />
                </svg>
            </div>

