            <div className={`absolute bottom-8 left-1/3 w-6 h-10 origin-bottom animate-sway opacity-60 transition-opacity duration-1000 delay-700 ${isBuilding ? 'opacity-0' : 'opacity-60'}`}>
                 <svg viewBox="0 0 100 100" fill="#22c55e">
                    <path d="M50,100 Q30,50 50,10 Q70,50 50,100 Z" />
                </svg>
            </div>

            {/* PEPINO & BUBBLE CONTAINER */}
            <div 
                className={`absolute w-14 h-14 transition-all duration-[3000ms] ease-in-out ${isBuilding ? 'opacity-0' : 'opacity-100'}`}
                style={{ 
                    left: `${fishPos.x}%`, 
                    top: `${fishPos.y}%`,
                    transform: `translate(-50%, -50%)`
                }}
            >
                 {/* Fish Wrapper - Instant Cut Direction + Constant Wiggle */}
                 <div className={`w-full h-full relative ${fishDirection === 'left' ? '-scale-x-100' : 'scale-x-100'} animate-wiggle`}>

                    {/* RED BETTA FISH SVG (Redesigned: Fuller Tail) */}
                    <svg viewBox="0 0 100 60" className="w-full h-full drop-shadow-sm filter" style={{ filter: 'drop-shadow(0 2px 2px rgba(0,0,0,0.1))' }}>
                         {/* Huge Flowing Tail */}
                         <path d="M15,30 C-10,10 5,-10 30,20 C40,25 35,35 30,40 C5,70 -10,50 15,30" fill="#ef4444" opacity="0.85" />
                         {/* Top Fin (Dorsal) - Larger */}
                         <path d="M45,20 Q35,-5 65,5 Q70,15 65,22" fill="#ef4444" opacity="0.9" />
                         {/* Bottom Fin (Anal) - Larger */}
                         <path d="M45,40 Q35,65 65,55 Q75,50 70,38" fill="#ef4444" opacity="0.9" />
                         {/* Body */}
                         <path d="M25,30 Q30,15 65,20 Q90,25 95,30 Q90,35 65,40 Q30,45 25,30 Z" fill="#ef4444" />
                         {/* Side Fin (Pectoral) */}
                         <path d="M60,30 Q55,35 63,40 Q67,35 60,30" fill="#fca5a5" opacity="0.8" />
                         {/* Eye */}
                         <circle cx="85" cy="27" r="1.5" fill="black" />
                    </svg>

                    {/* GIFT BUBBLE - Lined Icon, No Jump */}
                    {isGiftReady && (
                        <div 
                            onClick={handleClaim}
                            className={`absolute -top-7 left-1/2 -translate-x-1/2 z-20 cursor-pointer ${fishDirection === 'left' ? '-scale-x-100' : ''}`}
                        >
                            <div className="bg-white/80 backdrop-blur-sm p-1.5 rounded-full shadow-sm border border-blue-200 hover:scale-110 transition-transform">
                                {/* Lined Gift Icon */}
