    // Track if this is the immediate post-purchase view
    const [justUnlocked, setJustUnlocked] = useState(false);

    // Intercept purchase to set local "just unlocked" state if needed
    const handleBuyOfferWrapper = (offer: DiamondOffer) => {
        if (offer.type === 'support') {
            // We pass the offer up, but we assume the parent updates storage.
            // Actually, parent updates storage then re-renders this. 
            // We need a way to know if we JUST transitioned from locked to unlocked.
            // Since `pepinoState` comes from storage, we can use a ref or effect, 
            // but simply checking if it was locked and now is unlocked is tricky without previous state.
            // Simpler: The parent `finalizeRealMoneyPurchase` calls `Storage.unlockPepino()`.
            // We can rely on the fact that `FishTank` handles the intro if we pass a prop.
            // But we don't control the parent's state directly here.
            // The `pepinoState` is read from storage on render.
            // Let's assume if `pepinoState.unlocked` is true, and `pepinoState.nextGiftDelay` implies a fresh state (e.g. 10s delay), we show intro.
            // Or better: The parent `onBuyOffer` will eventually trigger a re-render.
            // Let's modify `onBuyOffer` to set a flag here locally? No, re-render will wipe it unless outside.
            // Actually, we can check `pepinoState.lastGiftTime`. If it's very recent (< 10s ago) and unlocked, show intro.
        }
        onBuyOffer(offer);
    };

    const shouldShowIntro = () => {
        if (!pepinoState.unlocked) return false;
        const now = Date.now();
        // If unlocked within the last 15 seconds, show intro
        // Note: unlockPepino sets lastGiftTime to Now.
        return (now - pepinoState.lastGiftTime) < 15000 && pepinoState.nextGiftDelay === 10000;
    };

    const handleRewardClaim = (amount: number, isPoop: boolean) => {
        if (amount > 0) {
            Storage.addPoints(amount);
            setRewardMessage(`+${amount}`);
        } else if (isPoop) {
            if (amount === 1) {
                Storage.addPoints(1);
                setRewardMessage("Cleaned! +1");
            }
        }
        setTimeout(() => setRewardMessage(null), 2000);
    };

    return (
        <div className="flex-1 w-full flex flex-col items-center overflow-hidden relative">
            {/* Background */}
            <DiamondBackground />

            {/* Locked Header */}
            <div className="w-full max-w-md flex items-center justify-between px-6 pt-[70px] pb-4 relative shrink-0 z-20">
                <button onClick={onBack} className="p-2 rounded-full hover:bg-stone-200 transition -ml-2 text-t-icon relative z-30">
                    <Icons.Back className="w-6 h-6 text-t-icon" />
                </button>

                <div className="flex flex-col items-center absolute left-0 right-0 pointer-events-none z-20">
                    <h1 className="text-xl font-bold text-t-primary leading-none">Diamond Shop</h1>
                    <p className="text-t-secondary text-[10px] font-bold tracking-widest uppercase mt-1">Get More</p>
                </div>

                <div className="flex items-center gap-1 bg-t-surface px-3 py-2 rounded-full shadow-sm relative z-30">
                      <span className="text-sm font-bold text-t-primary animate-pop">{points}</span>
                      <div className="text-blue-500"><Icons.Diamond className="w-3 h-3 fill-current" /></div>
                      {rewardMessage && (
                          <div className="absolute top-full right-0 mt-1 bg-green-500 text-white text-xs font-bold px-2 py-1 rounded-full animate-fade-in whitespace-nowrap">
                              {rewardMessage}
                          </div>
                      )}
                </div>
            </div>

            <div className="flex-1 w-full overflow-y-auto px-6 pb-6 hide-scrollbar flex flex-col items-center relative z-10">
                <div className="w-full max-w-md pt-2">

                    {/* SUPPORT DEVELOPER CARD OR FISH TANK */}
                    {pepinoState.unlocked ? (
                        <FishTank onRewardClaim={handleRewardClaim} showIntro={shouldShowIntro()} />
                    ) : (
                        DIAMOND_OFFERS.filter(o => o.type === 'support').map(offer => (
                            <button 
                                key={offer.id} 
                                onClick={() => handleBuyOfferWrapper(offer)}
                                // Increased height to h-52 (208px)
                                className="w-full h-52 relative overflow-hidden rounded-[1.75rem] p-6 shadow-xl transition-transform mb-6 text-left bg-rose-50 active:scale-[0.99] group border border-rose-100"
                            >
                                {/* Big Faded Heart Background (Opacity) */}
                                <div className="absolute -right-4 -bottom-8 opacity-[0.08] pointer-events-none">
                                     <svg viewBox="0 0 24 24" className="w-48 h-48 fill-current text-rose-500">
                                         <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/>
                                     </svg>
                                </div>

                                <div className="relative z-10 flex flex-col h-full justify-between">
                                    {/* Top Section */}
                                    <div className="flex justify-between items-start">
                                        <div className="flex-1">
                                            <h2 className="text-2xl font-bold text-stone-900 leading-tight mb-2">{offer.title}</h2>
                                            <p className="text-[11px] font-medium text-stone-600 leading-relaxed pr-8 max-w-[85%]">
                                                Oku is made by a single independent developer. 
                                                Your support helps keep the app calm, fair, and ad-light. 
                                                Thank you for being here.
                                            </p>
                                        </div>
                                        {/* Price Badge Container (kept but text changed to "Support") */}
                                        <div className="flex flex-col items-end">
                                            <div className="px-3 py-1.5 rounded-lg text-xs font-bold bg-white text-stone-900 shadow-sm min-w-[70px] text-center">
                                                Support
                                            </div>
                                        </div>
                                    </div>

                                    {/* Bottom Section - Features List */}
                                    <div className="flex flex-col gap-2 mt-auto">
                                        <div className="flex items-center gap-2">
                                            <Icons.Diamond className="w-4 h-4 text-blue-500 fill-current" />
                                            <span className="text-sm font-bold text-stone-800">+400</span>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <Icons.Sparkles className="w-4 h-4 text-amber-500" />
                                            <span className="text-sm font-bold text-stone-700">No forced ads, ever</span>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <span className="text-sm">🐟</span>
                                            <span className="text-sm font-bold text-stone-700">Special companion</span>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <span className="text-sm">🙏</span>
                                            <span className="text-sm font-bold text-stone-700">A personal thank-you</span>
                                        </div>
                                    </div>
                                </div>
                            </button>
                        ))
                    )}

                    {/* Watch Ad Button - Gold Design with Shimmer */}
                    <button 
                        onClick={onWatchAd} 
                        className="w-1/2 mx-auto block relative overflow-hidden bg-gradient-to-br from-amber-200 via-yellow-400 to-amber-500 bg-[length:200%_200%] animate-gradient rounded-2xl shadow-lg shadow-amber-500/30 active:scale-95 transition-transform group mb-8 border-t border-white/40"
                    >
                        <div className="py-3 flex items-center justify-center gap-3 relative z-10">
                            <div className="p-2 bg-white/20 rounded-xl backdrop-blur-sm border border-white/20 shadow-sm">
                                <Icons.Film className="w-6 h-6 text-stone-900" />
                            </div>

                            <div className="flex items-center gap-1.5 bg-white/30 px-3 py-1.5 rounded-xl backdrop-blur-md border border-white/20 shadow-sm">
                                 <span className="text-2xl font-bold tracking-tighter leading-none text-black">+25</span>
                                 <Icons.Diamond className="w-5 h-5 fill-current text-blue-600 drop-shadow-sm" />
                            </div>
                        </div>
                        {/* Shimmer overlay */}
                        <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/50 to-transparent z-20 animate-shimmer pointer-events-none" />
                    </button>

                    {DIAMOND_OFFERS.filter(o => o.type === 'starter').map(offer => {
                         // Check purchase state
                         const isPurchased = starterPackPurchased;

                         return (
                             <button 
                                key={offer.id} 
                                onClick={() => !isPurchased && onBuyOffer(offer)}
                                disabled={isPurchased}
                                // FIXED SIZE: h-40 (160px) - Increased from h-32 by 25%
                                className={`w-full h-40 relative overflow-hidden rounded-[1.75rem] p-5 shadow-xl transition-transform mb-6 text-left ${offer.gradientClass || 'bg-white'} ${isPurchased ? 'shadow-none opacity-50 grayscale cursor-not-allowed' : 'shadow-amber-900/5 active:scale-[0.99] group'}`}
                             >
                                {/* Big Faded Icon Logo on Side - Moved to background, smaller size */}
                                <div className="absolute right-3 -bottom-10 opacity-[0.07] pointer-events-none animate-spin-slow">
                                     <Icons.Diamond className="w-48 h-48 text-stone-900 fill-current" />
                                </div>

                                <div className="relative z-10 flex flex-row justify-between h-full items-stretch">
                                    {/* Left Side: Header & Features */}
                                    <div className="flex flex-col items-start justify-between flex-1 pr-4 py-0.5">
                                         <div>
                                             {/* Badge */}
                                             {!isPurchased && (
