};

import React, { useState, useEffect, useRef } from 'react';
import { Storage } from '../../utils/storage';
import { sounds } from '../../utils/sound';
import { Icons } from './Icons';
import { PepinoState } from '../../types';

interface FishTankProps {
    onRewardClaim: (amount: number, isPoop: boolean) => void;
    showIntro?: boolean;
}

export const FishTank: React.FC<FishTankProps> = ({ onRewardClaim, showIntro = false }) => {
    const [pepinoState, setPepinoState] = useState<PepinoState>(Storage.getPepinoState());
    const [isGiftReady, setIsGiftReady] = useState(false);
    const [poopVisible, setPoopVisible] = useState(false);
    const [rewardFeedback, setRewardFeedback] = useState<{amount: number, isPoop: boolean} | null>(null);

    // Intro State: 'message' -> 'building' -> 'active'
    const [introPhase, setIntroPhase] = useState<'message' | 'building' | 'active'>(showIntro ? 'message' : 'active');

    // Fish movement state
    const [fishPos, setFishPos] = useState({ x: 50, y: 50 }); // Percentage
    const [fishDirection, setFishDirection] = useState<'left' | 'right'>('right');
    const containerRef = useRef<HTMLDivElement>(null);

    // Handle Intro Flow
    useEffect(() => {
        if (showIntro) {
            const timer1 = setTimeout(() => {
                setIntroPhase('building');
                setTimeout(() => {
                    setIntroPhase('active');
                }, 1000); 
            }, 7000);
            return () => clearTimeout(timer1);
        }
    }, [showIntro]);

    // Timer check
    useEffect(() => {
        const checkTime = () => {
            const now = Date.now();
            const readyTime = pepinoState.lastGiftTime + pepinoState.nextGiftDelay;

            if (now >= readyTime) {
                setIsGiftReady(true);
            } else {
                setIsGiftReady(false);
            }
        };

        checkTime();
        const interval = setInterval(checkTime, 5000); 
        return () => clearInterval(interval);
    }, [pepinoState]);

    // Random Swimming Logic
    useEffect(() => {
        let timeoutId: any;

        const moveFish = () => {
            // Generate new target position
            const newX = 15 + Math.random() * 70;
            const newY = 30 + Math.random() * 50; 

            // Determine direction: Moving right (larger X) => Face Right
            setFishDirection(newX > fishPos.x ? 'right' : 'left');
            setFishPos({ x: newX, y: newY });

            const delay = 3000 + Math.random() * 5000;
            timeoutId = setTimeout(moveFish, delay);
        };

        moveFish();
        return () => clearTimeout(timeoutId);
    }, []); // Note: fishPos dependency removed to avoid re-trigger loops, we accept simple calc

    const handleClaim = (e: React.MouseEvent) => {
        e.stopPropagation();
        if (!isGiftReady && !poopVisible) return;

        const minDelay = 7200000;
        const maxDelay = 10800000;
        const nextDelay = Math.floor(Math.random() * (maxDelay - minDelay + 1) + minDelay);

        Storage.updatePepinoGiftTime(nextDelay);
        setPepinoState(Storage.getPepinoState()); 
        setIsGiftReady(false);

        if (poopVisible) {
            setPoopVisible(false);
            onRewardClaim(1, true); 
            setRewardFeedback({ amount: 1, isPoop: true });
            sounds.playPop();
            setTimeout(() => setRewardFeedback(null), 2000);
            return;
        }

        const r = Math.random();
        let amount = 5;
        let isPoop = false;

        if (r < 0.05) {
            isPoop = true;
            setPoopVisible(true);
            return; 
        } else if (r < 0.10) amount = 20;
        else if (r < 0.20) amount = 15;
        else if (r < 0.50) amount = 10;

        if (amount > 0) {
            sounds.playWin();
            onRewardClaim(amount, false);
            setRewardFeedback({ amount, isPoop: false });
            setTimeout(() => setRewardFeedback(null), 2000);
        }
    };

    if (introPhase === 'message') {
        return (
            <div className="w-full h-52 relative rounded-[1.75rem] overflow-hidden bg-[#e0f7fa] shadow-inner mb-6 flex items-center justify-center p-4">
                <div className="bg-white/60 backdrop-blur-md p-6 rounded-2xl shadow-sm border border-white/40 text-center max-w-[90%] animate-fade-in-medium">
                    <p className="text-xl font-bold text-stone-800 mb-2 leading-tight">This is Pepino.</p>
                    <p className="text-xs font-medium text-stone-600 mb-3 leading-relaxed">He was around while Oku was being built.</p>
                    <p className="text-[10px] text-stone-500 font-semibold opacity-90">Thanks for supporting the app — feel free to check on him anytime.</p>
                </div>
            </div>
        );
    }

    const isBuilding = introPhase === 'building';

    return (
        <div 
            ref={containerRef}
            className={`w-full h-52 relative rounded-[1.75rem] overflow-hidden bg-[#e0f7fa] shadow-inner mb-6 select-none transition-opacity duration-1000 ${isBuilding ? 'opacity-0' : 'opacity-100'}`}
        >
            {/* Water Gradient */}
            <div className="absolute inset-0 bg-gradient-to-b from-[#e0f7fa] via-[#e0f7fa] to-[#b2ebf2]" />

            {/* Background Decor (Sand Hills with Gradient) */}
            <div className={`absolute inset-x-0 bottom-0 h-24 w-full transition-transform duration-1000 ${isBuilding ? 'translate-y-full' : 'translate-y-0'}`}>
                <svg viewBox="0 0 100 24" preserveAspectRatio="none" className="w-full h-full">
                    <defs>
                        <linearGradient id="sandGradient" x1="0" x2="0" y1="0" y2="1">
                            <stop offset="0%" stopColor="#E3D8C8" />
                            <stop offset="100%" stopColor="#D6CBB8" />
                        </linearGradient>
                    </defs>
                    <path d="M0,24 L0,8 Q25,0 50,8 T100,12 L100,24 Z" fill="url(#sandGradient)" opacity="0.95" />
                </svg>
            </div>

            {/* Plants - Lowered to touch sand */}

            {/* Plant 1 - Left Back */}
            <div className={`absolute bottom-6 left-4 w-12 h-20 origin-bottom animate-sway-slow opacity-80 transition-opacity duration-1000 delay-300 ${isBuilding ? 'opacity-0' : 'opacity-80'}`}>
                <svg viewBox="0 0 100 100" fill="#4ade80">
                    <path d="M45,100 Q35,50 20,20 Q40,60 48,100 Z" />
                    <path d="M50,100 Q60,40 70,10 Q65,50 55,100 Z" />
                </svg>
            </div>

            {/* Plant 2 - Right Main */}
            <div className={`absolute bottom-4 right-8 w-10 h-16 origin-bottom animate-sway opacity-90 transition-opacity duration-1000 delay-500 ${isBuilding ? 'opacity-0' : 'opacity-90'}`}>
                <svg viewBox="0 0 100 100" fill="#86efac">
                    <path d="M50,100 C30,60 90,30 50,0 C60,40 40,70 60,100 Z" />
                    <path d="M50,100 Q20,50 10,20 Q30,60 45,100 Z" />
                </svg>
            </div>

            {/* Plant 3 - Middle Small */}
            <div className={`absolute bottom-5 left-1/3 w-8 h-12 origin-bottom animate-sway opacity-70 transition-opacity duration-1000 delay-700 ${isBuilding ? 'opacity-0' : 'opacity-70'}`}>
                 <svg viewBox="0 0 100 100" fill="#22c55e">
                    <path d="M50,100 Q40,50 50,10 Q60,50 50,100 Z" />
                    <path d="M50,100 Q80,60 90,30 Q70,70 55,100 Z" />
                </svg>
            </div>

            {/* Plant 4 - Far Right Small */}
            <div className={`absolute bottom-8 right-2 w-6 h-10 origin-bottom animate-sway-slow opacity-60 transition-opacity duration-1000 delay-200 ${isBuilding ? 'opacity-0' : 'opacity-60'}`}>
                 <svg viewBox="0 0 100 100" fill="#4ade80">
                    <path d="M50,100 Q60,50 40,10 Q50,50 50,100 Z" />
                </svg>
            </div>

            {/* PEPINO & BUBBLE CONTAINER */}
            <div 
                className={`absolute w-16 h-16 transition-all duration-[3000ms] ease-in-out ${isBuilding ? 'opacity-0' : 'opacity-100'}`}
                style={{ 
                    left: `${fishPos.x}%`, 
                    top: `${fishPos.y}%`,
                    transform: `translate(-50%, -50%)`
                }}
            >
                 {/* Fish Wrapper - Direction Flip & Wiggle */}
                 {/* SVG Default faces RIGHT. If direction is LEFT, flip it. */}
                 <div className={`w-full h-full relative ${fishDirection === 'left' ? '-scale-x-100' : 'scale-x-100'} animate-wiggle`}>

                    {/* RED BETTA FISH SVG (Rounded Nose, Big Eye) */}
                    <svg viewBox="0 0 100 60" className="w-full h-full drop-shadow-sm filter" style={{ filter: 'drop-shadow(0 2px 2px rgba(0,0,0,0.1))' }}>
                         {/* Tail */}
                         <path d="M15,30 C-10,10 5,-10 30,20 C40,25 35,35 30,40 C5,70 -10,50 15,30" fill="#ef4444" opacity="0.85" />
                         {/* Fins */}
                         <path d="M45,20 Q35,-5 65,5 Q70,15 65,22" fill="#ef4444" opacity="0.9" />
                         <path d="M45,40 Q35,65 65,55 Q75,50 70,38" fill="#ef4444" opacity="0.9" />
                         {/* Body - Round Nose */}
                         <path d="M25,30 Q30,15 65,20 Q88,20 92,30 Q88,40 65,40 Q30,45 25,30 Z" fill="#ef4444" />
                         {/* Side Fin */}
                         <path d="M60,30 Q55,35 63,40 Q67,35 60,30" fill="#fca5a5" opacity="0.8" />
                         {/* Big Eye */}
                         <circle cx="84" cy="27" r="2.5" fill="black" />
                         <circle cx="85" cy="26" r="0.8" fill="white" />
                    </svg>

                    {/* GIFT BUBBLE */}
                    {isGiftReady && (
                        <div 
                            onClick={handleClaim}
                            // Counter-flip the bubble if fish is flipped so icon stays upright
                            className={`absolute -top-8 left-1/2 -translate-x-1/2 z-20 cursor-pointer ${fishDirection === 'left' ? '-scale-x-100' : ''}`}
                        >
                            <div className="bg-white/80 backdrop-blur-sm p-1.5 rounded-full shadow-sm border border-blue-200 hover:scale-110 transition-transform animate-bubble-float">
                                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#3b82f6" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                    <rect x="3" y="8" width="18" height="4" rx="1" />
                                    <path d="M12 8v13" />
                                    <path d="M19 12v7a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2v-7" />
                                    <path d="M7.5 8a2.5 2.5 0 0 1 0-5A4.8 8 0 0 1 12 8a4.8 8 0 0 1 4.5-5 2.5 2.5 0 0 1 0 5" />
                                </svg>
                            </div>
                        </div>
                    )}
                 </div>
            </div>

            {/* POOP */}
            {poopVisible && (
                <div 
                    onClick={handleClaim}
                    className="absolute bottom-6 left-1/2 -translate-x-1/2 z-20 cursor-pointer hover:scale-110 transition-transform animate-bounce"
                >
                    <span className="text-xl filter drop-shadow-md">💩</span>
                </div>
            )}

            {/* REWARD FEEDBACK (Center Pill) */}
            {rewardFeedback && (
                <div className="absolute inset-0 flex items-center justify-center pointer-events-none z-30">
                    <div className="bg-white/90 backdrop-blur-md px-4 py-2 rounded-full shadow-lg flex items-center gap-2 animate-pop border border-white/50">
                        {rewardFeedback.isPoop ? (
                            <span className="text-sm font-bold text-stone-600">Cleaned!</span>
                        ) : (
                            <>
                                <span className="text-lg font-bold text-stone-800">+{rewardFeedback.amount}</span>
                                <Icons.Diamond className="w-5 h-5 text-blue-500 fill-current" />
                            </>
                        )}
                    </div>
                </div>
            )}

            {/* Tank Reflection */}
            <div className="absolute top-0 right-0 w-32 h-32 bg-gradient-to-bl from-white/30 to-transparent pointer-events-none rounded-bl-full" />
        </div>
    );
};

