                         {/* Fins */}
                         <path d="M45,20 Q35,-5 65,5 Q70,15 65,22" fill="#ef4444" opacity="0.9" />
                         <path d="M45,40 Q35,65 65,55 Q75,50 70,38" fill="#ef4444" opacity="0.9" />
                         {/* Body - Round Nose */}
                         <path d="M25,30 Q30,15 65,20 Q92,20 95,30 Q92,40 65,40 Q30,45 25,30 Z" fill="#ef4444" />
                         {/* Side Fin */}
                         <path d="M60,30 Q55,35 63,40 Q67,35 60,30" fill="#fca5a5" opacity="0.8" />
                         {/* Bigger Eye */}
                         <circle cx="86" cy="28" r="3.5" fill="black" />
                         <circle cx="87" cy="27" r="1.2" fill="white" />
                    </svg>

                    {/* GIFT BUBBLE - Static, Closer */}
                    {isGiftReady && (
                        <div 
                            onClick={handleClaim}
                            // Counter-flip bubble so icon stays upright
                            className="absolute -top-6 left-1/2 -translate-x-1/2 z-20 cursor-pointer"
                            style={{ transform: fishDirection === 'left' ? 'translateX(50%) scaleX(-1)' : 'translateX(-50%)' }}
                        >
                            <div className="bg-white/90 backdrop-blur-sm p-1.5 rounded-full shadow-sm border border-blue-200 hover:scale-110 transition-transform">
                                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#3b82f6" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                    <rect x="3" y="8" width="18" height="4" rx="1" />
                                    <path d="M12 8v13" />
                                    <path d="M19 12v7a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2v-7" />
                                    <path d="M7.5 8a2.5 2.5 0 0 1 0-5A4.8 8 0 0 1 12 8a4.8 8 0 0 1 4.5-5 2.5 2.5 0 0 1 0 5" />
                                </svg>
                            </div>
                        </div>
                    )}
                 </div>
            </div>

            {/* POOP */}
            {poopVisible && (
                <div 
                    onClick={handleClaim}
                    className="absolute bottom-6 left-1/2 -translate-x-1/2 z-20 cursor-pointer hover:scale-110 transition-transform animate-bounce"
                >
                    <span className="text-xl filter drop-shadow-md">💩</span>
                </div>
            )}

            {/* REWARD FEEDBACK (Center Pill - Scale In / Scale Out) */}
            {rewardFeedback && (
                <div 
                    className={`absolute inset-0 flex items-center justify-center pointer-events-none z-30 transition-all duration-300 ease-out ${
                        rewardExiting 
                        ? 'opacity-0 scale-90' 
                        : 'opacity-100 scale-100'
                    }`}
                >
                    <div className="bg-white/95 backdrop-blur-xl px-4 py-2 rounded-full shadow-lg flex items-center gap-2 border border-white/60 animate-scale-in">
                        {rewardFeedback.isPoop ? (
                            <span className="text-sm font-bold text-stone-600">Cleaned!</span>
                        ) : (
                            <>
                                <span className="text-lg font-bold text-stone-800">+{rewardFeedback.amount}</span>
                                <Icons.Diamond className="w-5 h-5 text-blue-500 fill-current" />
                            </>
                        )}
                    </div>
                </div>
            )}

            {/* Tank Reflection */}
            <div className="absolute top-0 right-0 w-32 h-32 bg-gradient-to-bl from-white/30 to-transparent pointer-events-none rounded-bl-full" />
        </div>
    );
};

