import React, { useState, useEffect, useRef } from 'react';
import { Storage } from '../../utils/storage';
import { sounds } from '../../utils/sound';
import { Icons } from './Icons';
import { PepinoState } from '../../types';

interface FishTankProps {
    onRewardClaim: (amount: number, isPoop: boolean) => void;
    showIntro?: boolean;
}

export const FishTank: React.FC<FishTankProps> = ({ onRewardClaim, showIntro = false }) => {
    const [pepinoState, setPepinoState] = useState<PepinoState>(Storage.getPepinoState());
    const [isGiftReady, setIsGiftReady] = useState(false);
    const [poopVisible, setPoopVisible] = useState(false);

    // Reward Feedback State
    const [rewardFeedback, setRewardFeedback] = useState<{amount: number, isPoop: boolean} | null>(null);
    const [rewardExiting, setRewardExiting] = useState(false);

    // Intro State: 'message' -> 'building' -> 'active'
    // Use lazy initializer to ensure prop is read correctly on mount
    const [introPhase, setIntroPhase] = useState<'message' | 'building' | 'active'>(() => showIntro ? 'message' : 'active');

    // Fish movement state
    const [fishPos, setFishPos] = useState({ x: 50, y: 50 }); // Percentage
    const [fishDirection, setFishDirection] = useState<'left' | 'right'>('right');
    const containerRef = useRef<HTMLDivElement>(null);

    // Handle Intro Flow
    useEffect(() => {
        if (showIntro) {
            const timer1 = setTimeout(() => {
                setIntroPhase('building');
                // Short buffer to allow DOM to paint the 'opacity-0' tank before fading in
                requestAnimationFrame(() => {
                    setTimeout(() => {
                        setIntroPhase('active');
                    }, 100); 
                });
            }, 7000);
            return () => clearTimeout(timer1);
        }
    }, [showIntro]);

    // Timer check
    useEffect(() => {
        const checkTime = () => {
            const now = Date.now();
            const readyTime = pepinoState.lastGiftTime + pepinoState.nextGiftDelay;

            if (now >= readyTime) {
                setIsGiftReady(true);
            } else {
                setIsGiftReady(false);
            }
        };

        checkTime();
        const interval = setInterval(checkTime, 5000); 
        return () => clearInterval(interval);
    }, [pepinoState]);

    // Random Swimming Logic
    useEffect(() => {
        let timeoutId: any;

        const moveFish = () => {
            // Generate new target position
            // X: 15-85% (avoid walls)
            const newX = 15 + Math.random() * 70;
            // Y: 35-75% (avoid top 30px absolute, stay off bottom sand)
            const newY = 35 + Math.random() * 40; 

            // Determine direction
            setFishDirection(newX > fishPos.x ? 'right' : 'left');
            setFishPos({ x: newX, y: newY });

            const delay = 4000 + Math.random() * 4000; // Slow, calm movement
            timeoutId = setTimeout(moveFish, delay);
        };

        // Initial delay before first move to let intro settle
        timeoutId = setTimeout(moveFish, 1000);

        return () => clearTimeout(timeoutId);
    }, []); // Empty dependency array: fishPos in closure is stale, but we use functional updates or just fresh randoms. 
            // Actually, we need current fishPos for direction. 
            // Better to use a ref for current pos or just compare newX to prevX in state setter?
            // Simplified: The closure captures initial state, subsequent moves are random. 
            // To fix direction properly without re-running effect:
            // We can just compare newX with the PREVIOUS newX (stored in a var outside the closure or ref).

    const handleClaim = (e: React.MouseEvent) => {
        e.stopPropagation();
        if ((!isGiftReady && !poopVisible) || rewardFeedback) return;

        const minDelay = 7200000;
        const maxDelay = 10800000;
        const nextDelay = Math.floor(Math.random() * (maxDelay - minDelay + 1) + minDelay);

        Storage.updatePepinoGiftTime(nextDelay);
        setPepinoState(Storage.getPepinoState()); 
        setIsGiftReady(false);

        if (poopVisible) {
            setPoopVisible(false);
            onRewardClaim(1, true); 
            showReward({ amount: 1, isPoop: true });
            sounds.playPop();
            return;
        }

        const r = Math.random();
        let amount = 5;
        let isPoop = false;

        if (r < 0.05) {
            isPoop = true;
            setPoopVisible(true);
            return; 
        } else if (r < 0.10) amount = 20;
        else if (r < 0.20) amount = 15;
        else if (r < 0.50) amount = 10;

        if (amount > 0) {
            sounds.playWin();
            onRewardClaim(amount, false);
            showReward({ amount, isPoop: false });
        }
    };

    const showReward = (feedback: {amount: number, isPoop: boolean}) => {
        setRewardFeedback(feedback);
        setRewardExiting(false);

        // Show for 2 seconds total
        setTimeout(() => {
            setRewardExiting(true);
            setTimeout(() => {
                setRewardFeedback(null);
                setRewardExiting(false);
            }, 300); 
        }, 1700);
    };

    // INTRO VIEW
    if (introPhase === 'message') {
        return (
            <div className="w-full h-56 relative rounded-[1.75rem] overflow-hidden bg-[#e0f7fa] shadow-inner mb-6 flex items-center justify-center p-4">
                <div className="absolute inset-0 bg-gradient-to-b from-[#e0f7fa] via-[#e0f7fa] to-[#b2ebf2]" />
                <div className="bg-white/60 backdrop-blur-md p-6 rounded-2xl shadow-sm border border-white/40 text-center max-w-[90%] animate-fade-in-medium relative z-10">
                    <p className="text-xl font-bold text-stone-800 mb-2 leading-tight">This is Pepino.</p>
                    <p className="text-xs font-medium text-stone-600 mb-3 leading-relaxed">He was around while Oku was being built.</p>
                    <p className="text-[10px] text-stone-500 font-semibold opacity-90">Thanks for supporting the app — feel free to check on him anytime.</p>
                </div>
            </div>
        );
    }

    const isBuilding = introPhase === 'building';

    return (
        <div 
            ref={containerRef}
            className={`w-full h-56 relative rounded-[1.75rem] overflow-hidden bg-[#e0f7fa] shadow-inner mb-6 select-none transition-opacity duration-1000 ${isBuilding ? 'opacity-0' : 'opacity-100'}`}
        >
            {/* Water Gradient */}
            <div className="absolute inset-0 bg-gradient-to-b from-[#e0f7fa] via-[#e0f7fa] to-[#b2ebf2]" />

            {/* Background Decor (Sand Hills with Gradient - Static) */}
            <div className={`absolute inset-x-0 bottom-0 h-28 w-full transition-transform duration-1000 ${isBuilding ? 'translate-y-full' : 'translate-y-0'}`}>
                <svg viewBox="0 0 100 28" preserveAspectRatio="none" className="w-full h-full">
                    <defs>
                        <linearGradient id="sandGradient" x1="0" x2="0" y1="0" y2="1">
                            <stop offset="0%" stopColor="#E3D8C8" />
                            <stop offset="100%" stopColor="#D6CBB8" />
                        </linearGradient>
                    </defs>
                    <path d="M0,28 L0,8 Q30,0 60,10 T100,6 L100,28 Z" fill="url(#sandGradient)" opacity="0.95" />
                </svg>
            </div>

            {/* --- FULLER PLANTS --- */}

            {/* Plant 1 - Left - Broad Leaves (Anubias style) */}
            <div className={`absolute bottom-6 left-4 w-16 h-20 origin-bottom animate-sway-slow opacity-90 transition-opacity duration-1000 delay-300 ${isBuilding ? 'opacity-0' : 'opacity-90'}`}>
                <svg viewBox="0 0 100 100" fill="#4ade80">
                    {/* Leaf 1 */}
                    <path d="M50,100 Q30,60 10,40 Q30,30 50,60 Q70,30 90,40 Q70,60 50,100 Z" />
                    {/* Leaf 2 */}
                    <path d="M50,100 Q60,70 80,50 Q90,40 70,30 Q50,60 50,100 Z" />
                    {/* Leaf 3 */}
                    <path d="M50,100 Q40,70 20,50 Q10,40 30,30 Q50,60 50,100 Z" />
                </svg>
            </div>

            {/* Plant 2 - Right - Tall Fern/Weed */}
            <div className={`absolute bottom-4 right-8 w-12 h-24 origin-bottom animate-sway opacity-80 transition-opacity duration-1000 delay-500 ${isBuilding ? 'opacity-0' : 'opacity-80'}`}>
                <svg viewBox="0 0 100 100" fill="#22c55e">
                    <path d="M45,100 Q45,60 20,20 Q50,40 55,100 Z" />
                    <path d="M55,100 Q55,60 80,20 Q50,40 45,100 Z" />
                    <path d="M50,100 Q50,50 50,10 Q60,50 50,100 Z" />
                </svg>
            </div>

            {/* Plant 3 - Middle Back - Bushy */}
            <div className={`absolute bottom-8 left-1/3 w-14 h-16 origin-bottom animate-sway-slow opacity-60 transition-opacity duration-1000 delay-700 ${isBuilding ? 'opacity-0' : 'opacity-60'}`}>
                 <svg viewBox="0 0 100 100" fill="#86efac">
                    <circle cx="50" cy="50" r="40" />
                    <path d="M50,100 L50,90" stroke="currentColor" strokeWidth="10" />
                </svg>
            </div>

            {/* PEPINO CONTAINER (Handles X/Y Position) */}
            <div 
                className={`absolute w-16 h-16 transition-all duration-[4000ms] ease-in-out ${isBuilding ? 'opacity-0' : 'opacity-100'}`}
                style={{ 
                    left: `${fishPos.x}%`, 
                    top: `${fishPos.y}%`,
                    transform: `translate(-50%, -50%)`
                }}
            >
                 {/* FISH SPRITE WRAPPER (Handles Direction Flip + Wiggle) */}
                 {/* Note: Gift is OUTSIDE this wrapper so it doesn't wiggle or flip improperly */}
                 <div 
                    className="w-full h-full relative animate-wiggle"
                    // Immediate flip for snappy turn
                    style={{ transform: fishDirection === 'left' ? 'scaleX(-1)' : 'scaleX(1)' }}
                 >
                    {/* RED BETTA FISH SVG (Rounded Nose, Bigger Eye) */}
                    <svg viewBox="0 0 100 60" className="w-full h-full drop-shadow-sm filter" style={{ filter: 'drop-shadow(0 4px 4px rgba(0,0,0,0.1))' }}>
                         {/* Tail (Fuller) */}
                         <path d="M15,30 C-15,5 0,-15 30,20 C40,25 35,35 30,40 C5,75 -15,55 15,30" fill="#ef4444" opacity="0.9" />
                         {/* Fins */}
                         <path d="M45,20 Q35,-10 70,0 Q75,15 65,22" fill="#ef4444" opacity="0.95" />
                         <path d="M45,40 Q35,70 70,60 Q80,50 70,38" fill="#ef4444" opacity="0.95" />
                         {/* Body - Round Nose */}
                         <path d="M25,30 Q30,15 65,20 Q95,20 98,30 Q95,40 65,40 Q30,45 25,30 Z" fill="#ef4444" />
                         {/* Side Fin */}
                         <path d="M60,30 Q55,35 63,40 Q67,35 60,30" fill="#fca5a5" opacity="0.9" />
                         {/* Huge Eye (White with Pupil) */}
                         <circle cx="88" cy="28" r="4" fill="white" />
                         <circle cx="89" cy="28" r="1.5" fill="black" />
                    </svg>
                 </div>

                 {/* GIFT BUBBLE - Fixed position relative to Fish Center, No Wiggle, No Flip */}
                 {isGiftReady && (
                        <div 
                            onClick={handleClaim}
                            className="absolute -top-8 left-1/2 -translate-x-1/2 z-20 cursor-pointer hover:scale-105 transition-transform"
                        >
                            <div className="bg-white/90 backdrop-blur-sm p-1.5 rounded-full shadow-md border border-blue-100/50">
                                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#3b82f6" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                    <rect x="3" y="8" width="18" height="4" rx="1" />
                                    <path d="M12 8v13" />
                                    <path d="M19 12v7a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2v-7" />
                                    <path d="M7.5 8a2.5 2.5 0 0 1 0-5A4.8 8 0 0 1 12 8a4.8 8 0 0 1 4.5-5 2.5 2.5 0 0 1 0 5" />
                                </svg>
                            </div>
                        </div>
                 )}
            </div>

            {/* POOP */}
            {poopVisible && (
                <div 
                    onClick={handleClaim}
                    className="absolute bottom-6 left-1/2 -translate-x-1/2 z-20 cursor-pointer hover:scale-110 transition-transform animate-bounce"
                >
                    <span className="text-xl filter drop-shadow-md">💩</span>
                </div>
            )}

            {/* REWARD FEEDBACK (Center Pill - Scale In / Scale Out) */}
            {rewardFeedback && (
                <div 
                    className={`absolute inset-0 flex items-center justify-center pointer-events-none z-50 transition-all duration-300 ease-out ${
                        rewardExiting 
                        ? 'opacity-0 scale-90' 
                        : 'opacity-100 scale-100'
                    }`}
                >
                    <div className="bg-white px-5 py-2.5 rounded-full shadow-xl flex items-center gap-2 border border-stone-100 animate-scale-in">
                        {rewardFeedback.isPoop ? (
                            <span className="text-sm font-bold text-stone-600">Cleaned!</span>
                        ) : (
                            <>
                                <span className="text-xl font-bold text-stone-800">+{rewardFeedback.amount}</span>
                                <Icons.Diamond className="w-5 h-5 text-blue-500 fill-current" />
                            </>
                        )}
                    </div>
                </div>
            )}

            {/* Tank Reflection */}
            <div className="absolute top-0 right-0 w-32 h-32 bg-gradient-to-bl from-white/30 to-transparent pointer-events-none rounded-bl-full" />
        </div>
    );
};

